import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Student Portrait là gì","description":"","frontmatter":{},"headers":[],"relativePath":"portrait/index.md","filePath":"portrait/index.md"}'),o={name:"portrait/index.md"};function r(g,n,c,u,e,m){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="student-portrait-la-gi" tabindex="-1">Student Portrait là gì <a class="header-anchor" href="#student-portrait-la-gi" aria-label="Permalink to &quot;Student Portrait là gì&quot;">​</a></h1><p>Trên trang này# Student Portrait là gì <a href="#student-portrait-la-gi">​</a> Learner Model trả lời &quot;con hiện tại là ai&quot;. Student Portrait trả lời một câu khác hẳn: <strong>&quot;chúng ta mong con trở thành người như thế nào?&quot;</strong> Đó là một chân dung tương lai — không phải kế hoạch, không phải cam kết, không phải danh sách chỉ tiêu. Một hình dung đủ cụ thể để cả nhà nhìn vào và nói được &quot;ừ, đúng cái này rồi&quot; hoặc &quot;không, con không muốn thế&quot;.</p><h2 id="vi-sao-no-can-ton-tai-thanh-mot-thu-rieng-​" tabindex="-1">Vì sao nó cần tồn tại thành một thứ riêng <a href="#vi-sao-no-can-ton-tai-thanh-mot-thu-rieng">​</a> <a class="header-anchor" href="#vi-sao-no-can-ton-tai-thanh-mot-thu-rieng-​" aria-label="Permalink to &quot;Vì sao nó cần tồn tại thành một thứ riêng [​](#vi-sao-no-can-ton-tai-thanh-mot-thu-rieng)&quot;">​</a></h2><p>Phần lớn gia đình có một hình dung như vậy trong đầu. Vấn đề là nó <strong>không được nói ra</strong>, nên ba chuyện xảy ra: Bố và mẹ hình dung khác nhau mà không ai biết — cho tới khi mâu thuẫn nổ ra ở một quyết định cụ thể như chọn trường. Con có hình dung của riêng mình, thường rất khác, và thường không được hỏi. Và vì không có hình dung nào được viết ra, mọi quyết định học tập rơi về thứ đo được dễ nhất: <strong>điểm số</strong>. Không phải vì ai tin điểm là quan trọng nhất, mà vì nó là thứ duy nhất hiện rõ trên bàn. Student Portrait tồn tại để đưa cái hình dung kia ra ánh sáng — chỗ mà cả nhà có thể cùng nhìn, cùng tranh luận, và cùng sửa.</p><h2 id="trong-mot-portrait-co-gi-​" tabindex="-1">Trong một Portrait có gì <a href="#trong-mot-portrait-co-gi">​</a> <a class="header-anchor" href="#trong-mot-portrait-co-gi-​" aria-label="Permalink to &quot;Trong một Portrait có gì [​](#trong-mot-portrait-co-gi)&quot;">​</a></h2><p>Mười mảng, và <strong>không mảng nào bắt buộc</strong>: MảngVí dụAcademic goalsVào chuyên Toán; IELTS 7.0 trước lớp 11CapabilitiesTự quản lý việc học; thuyết trình trước đám đôngInterestsThiên văn; lịch sử chiến tranh; xe cộLanguagesTiếng Anh học thuật; tiếng Trung giao tiếpSportsBơi đều đặn; bóng rổ trong đội trườngCreativeGuitar điện; vẽ truyện tranhPersonal developmentBớt sợ sai; dám hỏi khi không hiểuLifestyleNgủ đủ; có thời gian rảnh thật sựExperiencesMột chuyến đi xa không có bố mẹ; một dự án tự làm từ đầu tới cuốiCareerChưa biết — và <strong>để trống là hoàn toàn hợp lệ</strong>Chín trong mười mảng này không xuất hiện trên bất kỳ bảng điểm nào. Đó chính là lý do Portrait cần tồn tại: nếu chỉ nhìn vào thứ nhà trường đo, chín phần mười một đứa trẻ là vô hình.</p><h2 id="bon-nguyen-tac-​" tabindex="-1">Bốn nguyên tắc <a href="#bon-nguyen-tac">​</a> <a class="header-anchor" href="#bon-nguyen-tac-​" aria-label="Permalink to &quot;Bốn nguyên tắc [​](#bon-nguyen-tac)&quot;">​</a></h2><p><strong>Tối đa ba chân dung cùng lúc.</strong> Không phải một. Ba kịch bản khác nhau đặt cạnh nhau để so sánh và thảo luận — vì ép một gia đình chọn đúng một tương lai khi con mới 12 tuổi là ép sai chỗ. <a href="/portrait/vi-du">Xem ví dụ ba chân dung →</a><strong>Con luôn xem được, và luôn được phản hồi.</strong> Portrait về con thì con phải thấy. Con có quyền đánh dấu từng phần: <em>đồng ý · chưa chắc · không đồng ý</em>. Một chân dung con chưa từng đọc không phải chân dung — đó là kế hoạch của người lớn. <strong>Ý muốn của bố mẹ và ý muốn của con được lưu riêng.</strong> Không bao giờ trộn thành một con số. &quot;Tiếng Trung: con 2/5, bố mẹ 5/5&quot; phải hiện đúng như thế. Trung bình hoá con số này thành 3.5 là xoá mất thông tin quan trọng nhất — rằng hai bên đang không đồng ý. <strong>Bất đồng được nêu ra, không tự động dàn xếp.</strong> Hệ thống chỉ ra chỗ gia đình đang lệch nhau và gợi ý mở một cuộc trò chuyện. Nó không phán ai đúng, và không âm thầm nghiêng về phía nào.</p><h2 id="portrait-khong-đieu-khien-he-thong-​" tabindex="-1">Portrait không điều khiển hệ thống <a href="#portrait-khong-đieu-khien-he-thong">​</a> <a class="header-anchor" href="#portrait-khong-đieu-khien-he-thong-​" aria-label="Permalink to &quot;Portrait không điều khiển hệ thống [​](#portrait-khong-đieu-khien-he-thong)&quot;">​</a></h2><p>Đây là chỗ dễ hiểu nhầm. Viết &quot;IELTS 8.0 trước tháng 6&quot; vào Portrait <strong>không</strong> làm hệ thống dồn mọi thứ vào IELTS. Portrait là <strong>nguyện vọng</strong> — một đầu vào bên cạnh những đầu vào khác: con đang ở đâu, tuần này có bao nhiêu thời gian, đang sắp thi gì, còn lỗ hổng nền nào. Nếu nguyện vọng không khớp với thực tế, hệ thống <strong>giữ nguyên nguyện vọng</strong> và điều chỉnh các mốc trung gian — chứ không xoá mong muốn của gia đình, và cũng không giả vờ là nó khả thi. Chỉ khi gia đình chốt một phần của Portrait — có xác nhận rõ ràng — phần đó mới trở thành mục tiêu thật của hệ thống. Không có chuyện âm thầm chuyển ước mơ thành KPI.</p><h2 id="portrait-thay-đoi-va-đo-la-đieu-binh-thuong-​" tabindex="-1">Portrait thay đổi, và đó là điều bình thường <a href="#portrait-thay-đoi-va-đo-la-đieu-binh-thuong">​</a> <a class="header-anchor" href="#portrait-thay-đoi-va-đo-la-đieu-binh-thuong-​" aria-label="Permalink to &quot;Portrait thay đổi, và đó là điều bình thường [​](#portrait-thay-đoi-va-đo-la-đieu-binh-thuong)&quot;">​</a></h2><p>Một đứa trẻ 12 tuổi muốn làm phi hành gia, 15 tuổi mê dựng phim, 17 tuổi học kinh tế. Không có gì sai ở đây cả. Portrait có lịch sử phiên bản: mọi thay đổi được lưu lại, và không có gì bị xoá hẳn. Nhìn lại chuỗi Portrait qua ba năm là một trong những thứ giá trị nhất một gia đình có được — nó cho thấy con đã đổi thế nào, và cả bố mẹ đã đổi thế nào. Portrait không phải để dự đoán tương lai đúng. Nó là để cả nhà đang nói về <strong>cùng một</strong> tương lai — và biết rõ chỗ nào mình chưa đồng ý. <a href="/portrait/khac-diem-so">Khác gì mục tiêu điểm số →</a></p>',12)])])}const p=t(o,[["render",r]]);export{s as __pageData,p as default};
